SELECT DISTINCT names."primary" AS street_name
FROM lisbon_roads
WHERE names."primary" IS NOT NULL
  AND ST_Intersects(
        ST_Transform(geometry, 'EPSG:4326', 'EPSG:3763', always_xy := true),
        ST_Buffer(
          ST_Transform(ST_Point(-9.2160, 38.6916), 'EPSG:4326', 'EPSG:3763', always_xy := true),
          250
        )
      );
